[
  {
    "id": "spider-teapot-host",
    "source": null,
    "prompt": "Create an original premium storybook illustration: friendly brown spider next to a small teal floral teapot and one matching cup. Strict near-top-down composition. Spider occupies upper center, teapot and cup below right with clear gap from every leg. The spider has TWO main body segments and exactly FOUR PAIRS of legs, eight limbs total, all long segmented walking legs. Pair1 curves upper left and upper right. Pair2 extends middle left and middle right. Pair3 extends lower left and lower right. Pair4 extends down left and down right. Every leg fully distinct from tip to body; no overlap with props. No mouth palps or antennae or extra arms. Fine ink outline, polished smooth cel shading, natural brown broad tuft design without fine hair microtexture. Large charming eyes. Whole design well within central70% canvas with transparent margins. Actual alpha background and gaps. No text, halo, white fringe or shadow."
  },
  {
    "id": "spider-cookie-helper",
    "source": null,
    "prompt": "Create an original professional storybook clipart: a smiling charcoal-gray spider wears a small white chef hat. A cream bowl of cake batter with a wooden spoon rests BELOW and to its left, with empty space separating bowl from spider. Spider's one front leg points toward bowl but does not overlap it. Strict high overhead angle shows all EIGHT distinct segmented legs in FOUR PAIRS, four left and four right, one pair curves upwards, two pairs extend outward, last pair points downwards. All eight tips visible, no props conceal any legs. TWO body segments, not three. No arms, antennae or mouth palps. Polished smooth layered cel shading, thoughtfully designed broad fur tufts, confident dark outlines. Rich readable clean forms, no microhair or grain. Whole design central70%, genuine transparent margins and gaps, no text, halo, white fringe or shadow."
  },
  {
    "id": "spider-pumpkin-window",
    "source": "[workspace]/work/production/wave_152/source/spider-pumpkin-window.png",
    "prompt": "Edit this exact excellent spider emerging from an open pumpkin illustration. Preserve EIGHT legs in four pairs, face, pumpkin and lid arrangement. Complete the entire pumpkin lid stem that is clipped at the right edge. Frame the complete artwork smaller within the canvas with generous15% transparent margin on every side. Refine the surface into smooth polished layered cel shading and broad intentional fur tufts, no dense microtexture. Keep rich orange color, confident dark contours and charming volumes. Actual transparent background and gaps, no colored halo or white fringe. No text."
  }
]
